    100 => UA_LOGLEVEL_TRACE,
    200 => UA_LOGLEVEL_DEBUG,
    300 => UA_LOGLEVEL_INFO,
    400 => UA_LOGLEVEL_WARNING,
    500 => UA_LOGLEVEL_ERROR,
    600 => UA_LOGLEVEL_FATAL,
    _ => throw ArgumentError('Unknown value for UA_LogLevel: $value'),
  };
}

