    0 => UA_LOGCATEGORY_NETWORK,
    1 => UA_LOGCATEGORY_SECURECHANNEL,
    2 => UA_LOGCATEGORY_SESSION,
    3 => UA_LOGCATEGORY_SERVER,
    4 => UA_LOGCATEGORY_CLIENT,
    5 => UA_LOGCATEGORY_USERLAND,
